const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]}"></path></svg>`;
const $=s=>document.querySelector(s),num=n=>new Intl.NumberFormat(lang).format(n),pad=n=>new Intl.NumberFormat(lang,{minimumIntegerDigits:2,useGrouping:false}).format(n);
let chapters=[],glossary=null,current=null,articleUI,illustrationUI,fiches=[];const checked=new Map();
document.body.innerHTML=`<a class="skip-link" href="#content">${t.skip}</a><header class="masthead"><a class="brand" href="${base}"><span class="brand-icon">${icon('book')}</span><span><strong>${t.brand}</strong><span class="brand-sub">${t.sub}</span></span></a><nav class="header-nav" aria-label="${t.manual}"><a href="#sommaire">${icon('list')}<span>${t.toc}</span></a><a href="#glossaire">${icon('lex')}<span>${t.lex}</span></a></nav><div class="languages" aria-label="${ar?'اللغة':'Langue'}"><span class="language active" aria-current="true">${ar?'العربية':'FR'}</span><a class="language switch-language" href="${ar?'/fr/':'/ar/'}" lang="${ar?'fr':'ar'}">${ar?'FR':'العربية'}</a></div><button class="icon-button mobile-menu" aria-label="${t.toc}" aria-haspopup="dialog">${icon('list')}</button></header><div class="workspace"><aside class="sidebar"><div class="sidebar-top"><span class="eyebrow">${t.manual}</span><h2>${icon('list')} ${t.toc}</h2></div><nav class="toc-desktop" aria-label="${t.toc}"></nav><div class="sidebar-note">${icon('bulb')}<div><strong>${t.guide}</strong><p>${t.guideShort}</p></div></div></aside><main id="content" class="content" tabindex="-1"><p role="status">${t.loading}</p></main></div><dialog class="toc-dialog" aria-labelledby="toc-dialog-title"><div class="dialog-heading"><h2 id="toc-dialog-title">${t.toc}</h2><button class="icon-button close-menu" aria-label="${t.close}">${icon('close')}</button></div><nav class="toc-mobile" aria-label="${t.toc}"></nav></dialog>`;
$('.mobile-menu').addEventListener('click',()=>$('.toc-dialog').showModal());
$('.close-menu').addEventListener('click',()=>$('.toc-dialog').close());
$('.toc-dialog').addEventListener('click',e=>{if(e.target===$('.toc-dialog'))$('.toc-dialog').close()});
document.addEventListener('click',e=>{if(e.target.closest('.toc-dialog a'))$('.toc-dialog').close()});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#content').focus()});
const name=c=>c[lang],summary=c=>c[ar?'summaryAr':'summaryFr'],href=(c,mode='read')=>`#${c.id}${mode==='practice'?'/pratique':mode==='details'?'/tafsil':''}`;
function tocHTML(){return `<a class="toc-overview ${['illustrations','fiche'].includes(current.type)?'selected':''}" href="#makharij" ${['illustrations','fiche'].includes(current.type)?'aria-current="page"':''}>${icon('bulb')}${illustrationUI.label}</a>`+`<a class="toc-overview ${current.type==='contents'?'selected':''}" href="#sommaire" ${current.type==='contents'?'aria-current="page"':''}>${icon('book')}${t.overview}</a>`+chapterGroups.map((g,i)=>{const list=chapters.slice(g.start,g.end),active=list.some(c=>c.id===current.id);return `<details class="toc-group" ${active||!['chapter','article'].includes(current.type)?'open':''}><summary><span>${pad(i+1)} · ${t.groups[i]}</span>${icon('chevron')}</summary><div>${list.map(c=>`<a href="${href(c)}" class="toc-link ${c.id===current.id?'selected':''}" ${c.id===current.id?'aria-current="page"':''}><span class="toc-number">${pad(chapters.indexOf(c)+1)}</span><span>${esc(name(c))}</span></a>`).join('')}</div></details>`}).join('')+`<a href="#glossaire" class="toc-overview ${current.type==='glossary'?'selected':''}" ${current.type==='glossary'?'aria-current="page"':''}>${icon('lex')}${t.lex}</a>`}
const footer=()=>`<footer class="page-footer"><span>${t.title}</span><span>${t.edition}</span></footer>`;
const notice=()=>`<details class="editorial-note"><summary>${t.about}</summary><p>${t.note}</p><p>${t.sourceNote}</p></details>`;
const callout=(kind,title,body)=>`<aside class="callout ${kind}"><div class="callout-heading">${icon(kind==='warning'?'warning':'bulb')}<h2>${title}</h2></div><p>${esc(body)}</p></aside>`;
const verseHTML=v=>articleUI.verse(v);
function renderRead(c){const verses=c.verses;return `<div class="reading-layout"><div class="reading-main"><section class="paper poem"><div class="paper-heading"><h2>${icon('book')}${t.poem}</h2><span class="tag">${t.verses} ${num(c.id)}–${num(c.end)}</span></div><div class="verses">${verses.slice(0,2).map(verseHTML).join('')}</div>${verses.length>2?`<details class="more-verses"><summary>${icon('plus')} ${t.more} <span>+${num(verses.length-2)}</span></summary>${verses.slice(2).map(verseHTML).join('')}</details>`:''}</section><section class="paper explanation"><div class="paper-heading"><h2><span class="round-icon">${icon('bulb')}</span>${t.explain}</h2>${articleUI.briefButton(c.id)}</div><div class="explanation-text">${splitParagraphs(c[ar?'bodyAr':'bodyFr']).map(p=>`<p>${esc(p)}</p>`).join('')}</div></section><a class="practice-cta" href="${href(c,'practice')}"><span class="cta-icon">${icon('pencil')}</span><span><strong>${t.practice}</strong><small>${t.four}</small></span>${icon('arrow','directional')}</a></div><div class="reading-rail">${callout('remember',t.remember,summary(c))}${callout('warning',t.warning,t.oral)}<div class="rail-index"><span class="eyebrow">${t.chapter} ${pad(chapters.indexOf(c)+1)}</span><strong>${esc(name(c))}</strong><a href="#sommaire">${t.toc} ${icon('arrow','directional')}</a></div></div></div>`}
function renderPractice(c){const values=checked.get(c.id)||[false,false,false,false];return `<section class="paper practice-paper"><div class="practice-heading"><span class="practice-symbol">${icon('pencil')}</span><div><h2>${t.practiceTitle}</h2><p>${t.practiceIntro}</p></div></div><div class="practice-progress"><label for="practice-meter"><span id="done-count">${num(completionCount(values))}</span> / ${num(4)} ${t.checked}</label><progress id="practice-meter" max="4" value="${completionCount(values)}"></progress></div><fieldset class="exercise-steps"><legend>${t.checkPrompt}</legend>${t.steps.map((s,i)=>`<label class="exercise-step ${values[i]?'is-done':''}"><input type="checkbox" data-step="${i}" ${values[i]?'checked':''}><span class="step-number">${pad(i+1)}</span><span><strong>${s}</strong><small>${t.details[i]}</small></span></label>`).join('')}</fieldset><p class="session-note">${t.session}</p></section><section class="memory-card"><div class="callout-heading">${icon('bulb')}<h2>${t.memory}</h2></div><p>${t.memoryPrompt}</p><details class="answer-card"><summary>${t.reveal} ${icon('chevron')}</summary><p>${esc(summary(c))}</p></details></section>${callout('warning',t.oralTitle,t.oral)}`}
function renderChapter(){const i=chapters.findIndex(c=>c.id===current.id),c=chapters[i],gi=chapterGroups.findIndex(g=>i>=g.start&&i<g.end);document.title=`${name(c)} — ${t.title}`;$('#content').innerHTML=`<div class="breadcrumb"><a href="#sommaire">${t.toc}</a>${icon('chevron','directional')}<span>${t.groups[gi]}</span></div><section class="chapter-cover"><div class="cover-copy"><span class="eyebrow">${t.chapter} ${pad(i+1)} ${t.of} ${num(chapters.length)}</span><h1>${esc(name(c))}</h1><div class="cover-tags"><span>${icon('book')}${t.verses} ${num(c.id)}–${num(c.end)}</span><span>${t.explanationPractice}</span></div></div><div class="cover-number" aria-hidden="true">${pad(i+1)}</div></section><nav class="lesson-tabs" aria-label="${ar?'أجزاء الدرس':'Étapes du chapitre'}"><a href="${href(c)}" ${current.mode==='read'?'aria-current="page"':''}>${icon('book')} ${t.read}</a><a href="${href(c,'details')}" ${current.mode==='details'?'aria-current="page"':''}>${icon('lex')} ${articleUI.label}</a><a href="${href(c,'practice')}" ${current.mode==='practice'?'aria-current="page"':''}>${icon('pencil')} ${t.practice}</a></nav>${c.id===9?illustrationUI.banner():''}${current.mode==='practice'?renderPractice(c):current.mode==='details'?articleUI.index(c):renderRead(c)}<nav class="chapter-pagination" aria-label="${t.toc}">${i?`<a class="previous" href="${href(chapters[i-1])}">${icon('arrow','directional back')}<span><small>${t.prev}</small><strong>${esc(name(chapters[i-1]))}</strong></span></a>`:'<span></span>'}${i<chapters.length-1?`<a class="next" href="${href(chapters[i+1])}"><span><small>${t.next}</small><strong>${esc(name(chapters[i+1]))}</strong></span>${icon('arrow','directional')}</a>`:`<a class="next" href="#sommaire">${t.finished}${icon('check')}</a>`}</nav>${notice()}${footer()}`;document.querySelectorAll('[data-step]').forEach(input=>input.addEventListener('change',()=>{const values=checked.get(c.id)||[false,false,false,false];values[Number(input.dataset.step)]=input.checked;checked.set(c.id,values);input.closest('label').classList.toggle('is-done',input.checked);$('#done-count').textContent=num(completionCount(values));$('#practice-meter').value=completionCount(values)}))}
function renderContents(){document.title=`${t.toc} — ${t.title}`;$('#content').innerHTML=`<div class="breadcrumb">${t.manual}</div><section class="chapter-cover overview-cover"><div class="cover-copy"><span class="eyebrow">${t.tocBadge}</span><h1>${t.tocTitle}</h1><p>${t.tocIntro}</p></div><span class="cover-number" aria-hidden="true">${icon('list')}</span></section>${illustrationUI.banner()}<div class="overview-parts">${chapterGroups.map((g,i)=>`<section class="overview-part"><h2><span>${pad(i+1)}</span>${t.groups[i]}</h2><div class="chapter-grid">${chapters.slice(g.start,g.end).map(c=>`<a class="chapter-tile" href="${href(c)}"><span class="tile-number">${pad(chapters.indexOf(c)+1)}</span><h3>${esc(name(c))}</h3><p>${t.verses} ${num(c.id)}–${num(c.end)}</p><span class="tile-action">${t.open} ${icon('arrow','directional')}</span></a>`).join('')}</div></section>`).join('')}</div>${notice()}${footer()}`}
function renderGlossary(){document.title=`${t.lex} — ${t.title}`;$('#content').innerHTML=`<div class="breadcrumb"><a href="#sommaire">${t.toc}</a>${icon('chevron','directional')}<span>${t.lex}</span></div><section class="chapter-cover glossary-cover"><div class="cover-copy"><span class="eyebrow">${t.lex}</span><h1>${t.lexTitle}</h1><p>${t.lexIntro}</p></div><span class="cover-number" aria-hidden="true">${icon('lex')}</span></section><dl class="glossary-grid">${glossary[lang].map((s,i)=>{const [term,...rest]=s.split(' — ');return `<div class="term-card"><span class="term-index">${pad(i+1)}</span><dt>${esc(term)}</dt><dd ${ar?'':'lang="ar" dir="rtl"'}>${esc(rest.join(' — '))}</dd></div>`}).join('')}</dl>${notice()}${footer()}`}
function render(focus=false){current=resolveRoute(location.hash,chapters,fiches);document.body.classList.toggle('illustrated-page',['illustrations','fiche'].includes(current.type));$('.switch-language').href=(ar?'/fr/':'/ar/')+location.hash;if(current.type==='illustrations')illustrationUI.renderIndex($('#content'));else if(current.type==='fiche')illustrationUI.renderFiche(current.fiche,$('#content'));else if(current.type==='article')articleUI.renderArticle(current.verse,$('#content'));else if(current.type==='chapter')renderChapter();else if(current.type==='contents')renderContents();else renderGlossary();const html=tocHTML();$('.toc-desktop').innerHTML=html;$('.toc-mobile').innerHTML=html;document.querySelectorAll('.header-nav a').forEach(a=>{if(a.hash===location.hash)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(focus){window.scrollTo({top:0,behavior:'instant'});$('#content').focus({preventScroll:true})}}
async function boot(){try{[chapters,glossary,fiches]=await Promise.all(['/content.json','/glossary.json','/makharij.json'].map(async path=>{const r=await fetch(path);if(!r.ok)throw Error(path);return r.json()}));if(!chapters.length||!Array.isArray(glossary[lang]))throw Error('Invalid content');illustrationUI=createMakharij({ar,lang,fiches,chapters,icon,num,footer,verse:v=>articleUI.verse(v)});articleUI=createArticles({ar,lang,chapters,icon,num,footer,fiches,illustrationUI});render();window.addEventListener('hashchange',()=>render(true))}catch{$('#content').innerHTML=`<section class="paper error-panel"><h1>${t.error}</h1><button class="button retry">${t.retry}</button></section>`;$('.retry').addEventListener('click',()=>location.reload())}}
boot();
